{"theorem_id":"CL-T01","title":"Multiplicative weights and additive event log weights","status":"ALGEBRAIC_THEOREM","statement":"Matching fixed rules multiply event weights; their logarithms add.","assumptions":["Positive baseline and multipliers","H=L=0; fixed rule occurrences"],"scope":"Declared finite fixed-current-state DSL; see assumptions, not an ontology theorem.","proof_or_verification":{"proof_sketch":"Constructive derivation or exact identity in the linked proof section; implementation fixtures in test_formal.py.","derivation_ref":"constraint-lab/formal/derivations.md#cl-t01"},"source_generations":["008D","008G"],"evidence_refs":["constraint-lab/formal/derivations.md","constraint-lab/tests/test_formal.py","constraint-lab/src/rs_constraint_lab/kernel.py"],"coherence_refs":["F8D-LOG-ADDITIVITY","F8D-ADDITIVE-FEATURE-GRAMMAR","F8G-FORMAL-ADDITIVE-LOGIT-GRAMMAR"],"counterexample_scope":"Zero prohibit is outside logarithmic algebra.","dependencies":[],"notes":"Zero prohibit is outside logarithmic algebra."}
{"theorem_id":"CL-T02","title":"Rule-order commutativity, not idempotence","status":"ALGEBRAIC_THEOREM","statement":"Rule permutations preserve exact weights and kernels; duplicate occurrences still multiply repeatedly.","assumptions":["Exact arithmetic","Same factor map and rule multiset"],"scope":"Declared finite fixed-current-state DSL; see assumptions, not an ontology theorem.","proof_or_verification":{"proof_sketch":"Constructive derivation or exact identity in the linked proof section; implementation fixtures in test_formal.py.","derivation_ref":"constraint-lab/formal/derivations.md#cl-t02"},"source_generations":["008D","008G"],"evidence_refs":["constraint-lab/formal/derivations.md","constraint-lab/tests/test_formal.py","constraint-lab/src/rs_constraint_lab/grammar.py"],"coherence_refs":["F8D-LOG-ADDITIVITY","F8G-FORMAL-ADDITIVE-LOGIT-GRAMMAR"],"counterexample_scope":"Structurally simple census sets forbid repeated structural identity; backend multisets do not deduplicate.","dependencies":["CL-T01"],"notes":"Structurally simple census sets forbid repeated structural identity; backend multisets do not deduplicate."}
{"theorem_id":"CL-T03","title":"Six pair-slot normalised law","status":"ALGEBRAIC_THEOREM","statement":"One weighted admissible pair slot has q(action)=m/(m+5), all alternatives 1/(m+5).","assumptions":["Six pair slots","Other five weights 1","Immediate pair-event conditioning"],"scope":"Declared finite fixed-current-state DSL; see assumptions, not an ontology theorem.","proof_or_verification":{"proof_sketch":"Constructive derivation or exact identity in the linked proof section; implementation fixtures in test_formal.py.","derivation_ref":"constraint-lab/formal/derivations.md#cl-t03"},"source_generations":["008C","008G"],"evidence_refs":["constraint-lab/formal/derivations.md","constraint-lab/tests/test_formal.py"],"coherence_refs":["F8C-CLOSED-FORM-CMI","F8C-TWO-COORDINATES"],"counterexample_scope":"Outside the stated feature, support, positivity and clock assumptions; no physical universality claim.","dependencies":["CL-T01"],"notes":""}
{"theorem_id":"CL-T04","title":"Complementary equal-gate elimination","status":"ALGEBRAIC_THEOREM","statement":"Equal same-direction factors on G and NOT G equal an unconditional factor, including the full kernel.","assumptions":["Binary complementary gate","Equal positive multipliers","Same action and direction"],"scope":"Declared finite fixed-current-state DSL; see assumptions, not an ontology theorem.","proof_or_verification":{"proof_sketch":"Constructive derivation or exact identity in the linked proof section; implementation fixtures in test_formal.py.","derivation_ref":"constraint-lab/formal/derivations.md#cl-t04"},"source_generations":["007B","008D","008G"],"evidence_refs":["constraint-lab/formal/derivations.md","constraint-lab/tests/test_formal.py"],"coherence_refs":["F8D-COMPLEMENTARY-ELIMINATION","F009-TWO-LEVEL-COLLAPSE"],"counterexample_scope":"Outside the stated feature, support, positivity and clock assumptions; no physical universality claim.","dependencies":["CL-T01"],"notes":""}
{"theorem_id":"CL-T05","title":"Equal-direction elimination","status":"ALGEBRAIC_THEOREM","statement":"Equal form and dissolve factors on the same gate remove action-bit dependence of slot weight but retain gate dependence.","assumptions":["One action slot","Same positive multiplier and gate in both directions"],"scope":"Declared finite fixed-current-state DSL; see assumptions, not an ontology theorem.","proof_or_verification":{"proof_sketch":"Constructive derivation or exact identity in the linked proof section; implementation fixtures in test_formal.py.","derivation_ref":"constraint-lab/formal/derivations.md#cl-t05"},"source_generations":["008D","008G"],"evidence_refs":["constraint-lab/formal/derivations.md","constraint-lab/tests/test_formal.py"],"coherence_refs":["F8D-DIRECTION-ELIMINATION"],"counterexample_scope":"Outside the stated feature, support, positivity and clock assumptions; no physical universality claim.","dependencies":["CL-T01"],"notes":""}
{"theorem_id":"CL-T06","title":"K2 literal additive-gate bound","status":"ALGEBRAIC_THEOREM","statement":"Same-action one-literal rules give c+aG1+bG2 and zero second discrete log-weight derivative.","assumptions":["Fixed admissible direction","Pure literal fragment","One-action gauge"],"scope":"Declared finite fixed-current-state DSL; see assumptions, not an ontology theorem.","proof_or_verification":{"proof_sketch":"Constructive derivation or exact identity in the linked proof section; implementation fixtures in test_formal.py.","derivation_ref":"constraint-lab/formal/derivations.md#cl-t06"},"source_generations":["008D","008E","008G"],"evidence_refs":["constraint-lab/formal/derivations.md","constraint-lab/tests/test_formal.py"],"coherence_refs":["F8D-NO-GATE-PRODUCT","F8D-ADDITIVE-FEATURE-GRAMMAR","F8G-FORMAL-K-INTERACTION-HIERARCHY"],"counterexample_scope":"Not a bound for count predicates, probabilities or arbitrary higher-K rules.","dependencies":["CL-T01"],"notes":"Not a bound for count predicates, probabilities or arbitrary higher-K rules."}
{"theorem_id":"CL-T07","title":"K3 conjunction and polarity sign","status":"ALGEBRAIC_THEOREM","statement":"A non-neutral two-distinct-literal rule has literal second derivative ln(m); raw-bit coefficient changes sign with each absent literal.","assumptions":["Two distinct satisfiable gate variables","Admissible action","m>0 and m!=1","Non-action gates span their full cube under fixed action admissibility"],"scope":"Declared finite fixed-current-state DSL; see assumptions, not an ontology theorem.","proof_or_verification":{"proof_sketch":"Constructive derivation or exact identity in the linked proof section; implementation fixtures in test_formal.py.","derivation_ref":"constraint-lab/formal/derivations.md#cl-t07"},"source_generations":["008E","008G"],"evidence_refs":["constraint-lab/formal/derivations.md","constraint-lab/tests/test_formal.py"],"coherence_refs":["F8E-K3-CONJUNCTION-INTERACTION","F8E-K2-K3-NONREPRESENTABILITY","F8G-FORMAL-K-INTERACTION-HIERARCHY"],"counterexample_scope":"Outside the stated feature, support, positivity and clock assumptions; no physical universality claim.","dependencies":["CL-T01"],"notes":""}
{"theorem_id":"CL-T08","title":"Scoped general conjunction degree","status":"ALGEBRAIC_THEOREM","statement":"A non-neutral rule over r distinct jointly satisfiable literals has nonzero degree-r raw-gate coefficient ln(m)*(-1)^number_absent.","assumptions":["Distinct gate variables","Joint satisfiability","Positive non-neutral factor","Admissible action","Non-action gates span their full cube under fixed action admissibility"],"scope":"Declared finite fixed-current-state DSL; see assumptions, not an ontology theorem.","proof_or_verification":{"proof_sketch":"Constructive derivation or exact identity in the linked proof section; implementation fixtures in test_formal.py.","derivation_ref":"constraint-lab/formal/derivations.md#cl-t08"},"source_generations":["008E","008F","008G"],"evidence_refs":["constraint-lab/formal/derivations.md","constraint-lab/tests/test_formal.py"],"coherence_refs":["F8E-GENERAL-K-INTERACTION","F8F-GENERAL-K-SCOPE","F8E-CARDINALITY-VS-K","F8G-FORMAL-K-INTERACTION-HIERARCHY"],"counterexample_scope":"Contradiction, repeated variable, neutral multiplier or cross-rule cancellation defeats naive syntactic degree claims.","dependencies":["CL-T01"],"notes":"Contradiction, repeated variable, neutral multiplier or cross-rule cancellation defeats naive syntactic degree claims."}
{"theorem_id":"CL-T09","title":"Unique Boolean Mobius expansion","status":"ALGEBRAIC_THEOREM","statement":"Every real function on r Boolean gates has unique multilinear coefficients given by alternating subset sums.","assumptions":["Finite Boolean cube","Real-valued table"],"scope":"Declared finite fixed-current-state DSL; see assumptions, not an ontology theorem.","proof_or_verification":{"proof_sketch":"Constructive derivation or exact identity in the linked proof section; implementation fixtures in test_formal.py.","derivation_ref":"constraint-lab/formal/derivations.md#cl-t09"},"source_generations":["008E","008G"],"evidence_refs":["constraint-lab/formal/derivations.md","constraint-lab/tests/test_formal.py"],"coherence_refs":["F8E-BOOLEAN-LOGIT-BASIS","F8G-FORMAL-BOOLEAN-BASIS"],"counterexample_scope":"Outside the stated feature, support, positivity and clock assumptions; no physical universality claim.","dependencies":[],"notes":""}
{"theorem_id":"CL-T10","title":"Corner-indicator basis","status":"ALGEBRAIC_THEOREM","statement":"Complete literal corners are mutually exclusive basis vectors, transformed to monomials by expanding absent literals.","assumptions":["r distinct Boolean gates","All cube corners available"],"scope":"Declared finite fixed-current-state DSL; see assumptions, not an ontology theorem.","proof_or_verification":{"proof_sketch":"Constructive derivation or exact identity in the linked proof section; implementation fixtures in test_formal.py.","derivation_ref":"constraint-lab/formal/derivations.md#cl-t10"},"source_generations":["008E","008G"],"evidence_refs":["constraint-lab/formal/derivations.md","constraint-lab/tests/test_formal.py"],"coherence_refs":["F8E-CORNER-BASIS","F8E-BOOLEAN-LOGIT-BASIS","F8G-FORMAL-BOOLEAN-BASIS"],"counterexample_scope":"Outside the stated feature, support, positivity and clock assumptions; no physical universality claim.","dependencies":["CL-T09"],"notes":""}
{"theorem_id":"CL-T11","title":"Continuous one-action weight expressivity","status":"ALGEBRAIC_THEOREM","statement":"Arbitrary positive corner multipliers construct any positive action-weight table with at most 2^r rules and K=r+1.","assumptions":["One fixed action and admissible direction","Arbitrary positive factors","Unbounded rule budget","Literal parser permits all selected non-action gates"],"scope":"Declared finite fixed-current-state DSL; see assumptions, not an ontology theorem.","proof_or_verification":{"proof_sketch":"Constructive derivation or exact identity in the linked proof section; implementation fixtures in test_formal.py.","derivation_ref":"constraint-lab/formal/derivations.md#cl-t11"},"source_generations":["008E","008G"],"evidence_refs":["constraint-lab/formal/derivations.md","constraint-lab/tests/test_formal.py"],"coherence_refs":["F8E-BOOLEAN-LOGIT-BASIS","F8E-CORNER-BASIS","F8G-FORMAL-BOOLEAN-BASIS"],"counterexample_scope":"Continuous algebraic completeness is not W4 coverage or arbitrary full-kernel universality.","dependencies":["CL-T10"],"notes":"Continuous algebraic completeness is not W4 coverage or arbitrary full-kernel universality."}
{"theorem_id":"CL-T12","title":"Restricted full current-state expressivity","status":"ALGEBRAIC_THEOREM","statement":"The unbounded literal parser/backend constructs every positive event-weight table on its finite single-toggle support using K<=D and J<=D*2^D.","assumptions":["O=2 or O=3 independent relation bits","Both event directions and all non-action literals","Positive slot baselines","Custom positive factor map","No experiment-runner J/W bound"],"scope":"Declared finite fixed-current-state DSL; see assumptions, not an ontology theorem.","proof_or_verification":{"proof_sketch":"Constructive derivation or exact identity in the linked proof section; implementation fixtures in test_formal.py.","derivation_ref":"constraint-lab/formal/derivations.md#cl-t12"},"source_generations":["008G"],"evidence_refs":["constraint-lab/formal/derivations.md","constraint-lab/tests/test_formal.py","constraint-lab/src/rs_constraint_lab/constraints.py","constraint-lab/src/rs_constraint_lab/spec.py"],"coherence_refs":["F8D-ADDITIVE-FEATURE-GRAMMAR","F8E-BOOLEAN-LOGIT-BASIS","Q-H-POSITIVE","Q-META-CONSTRAINT","F8G-FORMAL-CURRENT-STATE-EXPRESSIVITY","F8G-FORMAL-COMPILATION-TEST"],"counterexample_scope":"Not arbitrary support, self-loop, multibit, history or standard finite-alphabet experiment expressivity.","dependencies":["CL-T10","CL-T11"],"notes":"Not arbitrary support, self-loop, multibit, history or standard finite-alphabet experiment expressivity."}
{"theorem_id":"CL-T13","title":"Rule cardinality preserves a fixed feature span","status":"ALGEBRAIC_THEOREM","statement":"Adding more terms from a fixed feature family cannot create an absent log-weight monomial.","assumptions":["Fixed multiplicative current-state grammar","Fixed primitive feature family and gauge"],"scope":"Declared finite fixed-current-state DSL; see assumptions, not an ontology theorem.","proof_or_verification":{"proof_sketch":"Constructive derivation or exact identity in the linked proof section; implementation fixtures in test_formal.py.","derivation_ref":"constraint-lab/formal/derivations.md#cl-t13"},"source_generations":["008D","008E","008G"],"evidence_refs":["constraint-lab/formal/derivations.md","constraint-lab/tests/test_formal.py"],"coherence_refs":["F8E-CARDINALITY-VS-K","F8D-GATE-DIMENSION","F8G-FORMAL-RULE-CARDINALITY-DISTINCTION"],"counterexample_scope":"Outside the stated feature, support, positivity and clock assumptions; no physical universality claim.","dependencies":["CL-T01","CL-T09"],"notes":""}
{"theorem_id":"CL-T14","title":"Count-token counterexample to a blanket K bound","status":"ALGEBRAIC_THEOREM","statement":"At O=2,N=3 on a form-admissible action, one K2 count>=1 token equals G1+G2-G1G2 and has interaction order 2.","assumptions":["Two remaining pair bits","Action bit fixed absent","O=2 count semantics"],"scope":"Declared finite fixed-current-state DSL; see assumptions, not an ontology theorem.","proof_or_verification":{"proof_sketch":"Constructive derivation or exact identity in the linked proof section; implementation fixtures in test_formal.py.","derivation_ref":"constraint-lab/formal/derivations.md#cl-t14"},"source_generations":["008G"],"evidence_refs":["constraint-lab/formal/derivations.md","constraint-lab/tests/test_formal.py","constraint-lab/src/rs_constraint_lab/constraints.py"],"coherence_refs":["F8E-CARDINALITY-VS-K","F8F-GENERAL-K-SCOPE","F8G-FORMAL-COUNT-SCOPE"],"counterexample_scope":"The K-1 degree hierarchy applies to pure literal conjunctions, not the entire count-token DSL.","dependencies":["CL-T09"],"notes":"The K-1 degree hierarchy applies to pure literal conjunctions, not the entire count-token DSL."}
{"theorem_id":"CL-T15","title":"Next-pair resolvent and stationary arrival weighting","status":"ALGEBRAIC_THEOREM","statement":"If P=T+B and rho(T)<1, E=(I-T)^-1 B; full-event stationary pi induces epoch stationary rho proportional to pi B.","assumptions":["Finite kernel","T hidden-only and B pair-event transitions","Almost-sure pair arrival and rho(T)<1"],"scope":"Declared finite fixed-current-state DSL; see assumptions, not an ontology theorem.","proof_or_verification":{"proof_sketch":"Constructive derivation or exact identity in the linked proof section; implementation fixtures in test_formal.py.","derivation_ref":"constraint-lab/formal/derivations.md#cl-t15"},"source_generations":["003C","008C","008F","008G"],"evidence_refs":["constraint-lab/formal/derivations.md","constraint-lab/tests/test_formal.py"],"coherence_refs":["F003-CLOCK-SPLIT","F8C-CHECKPOINT-EPOCH","F8F-COMPLEMENT-PERIOD","F8G-FORMAL-STATIONARY-FACTORISATION"],"counterexample_scope":"Outside the stated feature, support, positivity and clock assumptions; no physical universality claim.","dependencies":[],"notes":""}
{"theorem_id":"CL-T16","title":"Nested projection information chain","status":"ALGEBRAIC_THEOREM","statement":"I(M;mask)=I(M;edges)+I(M;class|edges)+I(M;mask|class) for deterministic nested projections.","assumptions":["Class is a function of mask","Edge count is a function of class","Well-defined finite joint distribution"],"scope":"Declared finite fixed-current-state DSL; see assumptions, not an ontology theorem.","proof_or_verification":{"proof_sketch":"Constructive derivation or exact identity in the linked proof section; implementation fixtures in test_formal.py.","derivation_ref":"constraint-lab/formal/derivations.md#cl-t16"},"source_generations":["008C","008F","008G"],"evidence_refs":["constraint-lab/formal/derivations.md","constraint-lab/tests/test_formal.py"],"coherence_refs":["F8F-INTERACTION-ROUTING","F8C-PROJECTION-GEOMETRY"],"counterexample_scope":"Outside the stated feature, support, positivity and clock assumptions; no physical universality claim.","dependencies":[],"notes":""}
{"theorem_id":"CL-T17","title":"Pair-epoch parity and period two","status":"ALGEBRAIC_THEOREM","statement":"One-bit pair epochs flip parity; irreducibility and positive two-step reverse moves imply period exactly two.","assumptions":["Positive finite single-toggle support","At least one pair slot","Next-pair absorption"],"scope":"Declared finite fixed-current-state DSL; see assumptions, not an ontology theorem.","proof_or_verification":{"proof_sketch":"Constructive derivation or exact identity in the linked proof section; implementation fixtures in test_formal.py.","derivation_ref":"constraint-lab/formal/derivations.md#cl-t17"},"source_generations":["008F","008G"],"evidence_refs":["constraint-lab/formal/derivations.md","constraint-lab/tests/test_formal.py"],"coherence_refs":["F8F-COMPLEMENT-PERIOD"],"counterexample_scope":"Bipartiteness alone only implies even return lengths, not period exactly two.","dependencies":["CL-T15"],"notes":"Bipartiteness alone only implies even return lengths, not period exactly two."}
{"theorem_id":"CL-T18","title":"Autonomous single-action stationary factorisation","status":"ALGEBRAIC_THEOREM","statement":"One action depending only on its bit and hidden bits yields action occupancy times uniform other pair bits under both full and pair-arrival stationary clocks.","assumptions":["Action weight w(b,y)>0 independent of other pairs z","Other pair and hidden flip rates symmetric unit","Complete independent-bit support"],"scope":"Declared finite fixed-current-state DSL; see assumptions, not an ontology theorem.","proof_or_verification":{"proof_sketch":"Constructive derivation or exact identity in the linked proof section; implementation fixtures in test_formal.py.","derivation_ref":"constraint-lab/formal/derivations.md#cl-t18"},"source_generations":["008F","008G"],"evidence_refs":["constraint-lab/formal/derivations.md","constraint-lab/tests/test_formal.py"],"coherence_refs":["F8F-SHAPE-WASHES-OUT","F8F-INTERACTION-ROUTING","F8G-FORMAL-STATIONARY-FACTORISATION"],"counterexample_scope":"Explicit other-pair-conditioned action counterexample in derivations; does not cover multiple coupled actions.","dependencies":["CL-T15"],"notes":"Explicit other-pair-conditioned action counterexample in derivations; does not cover multiple coupled actions."}
{"theorem_id":"CL-T19","title":"Stationary shape-given-edge invariance","status":"ALGEBRAIC_THEOREM","statement":"In the factorised family, graph-class conditional probabilities at fixed edge count are orbit sizes divided by binomial(p,k), independent of action occupancy.","assumptions":["CL-T18 hypotheses","Vertex group transitive on pair slots","Declared unlabelled graph classes"],"scope":"Declared finite fixed-current-state DSL; see assumptions, not an ontology theorem.","proof_or_verification":{"proof_sketch":"Constructive derivation or exact identity in the linked proof section; implementation fixtures in test_formal.py.","derivation_ref":"constraint-lab/formal/derivations.md#cl-t19"},"source_generations":["008F","008G"],"evidence_refs":["constraint-lab/formal/derivations.md","constraint-lab/tests/test_formal.py"],"coherence_refs":["F8F-SHAPE-WASHES-OUT","F8F-INTERACTION-ROUTING","Q-SCALE-N","F8G-FORMAL-SHAPE-INVARIANCE"],"counterexample_scope":"Scales beyond N=4 within the same family; N alone or XOR alone cannot defeat this theorem.","dependencies":["CL-T18"],"notes":"Scales beyond N=4 within the same family; N alone or XOR alone cannot defeat this theorem."}
